css:
.d-at{width:100%;max-width:340px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-at-head{display:flex;align-items:center;justify-content:space-between;padding:8px 12px;border-bottom:1px solid var(--line)}
.d-at-head button{padding:4px 12px;border:1px solid var(--line);border-radius:999px;background:var(--bg);color:var(--ink);font:inherit;font-size:11px;cursor:pointer}
.d-at-head span{font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;color:var(--faint)}
.d-at-list{list-style:none;margin:0;padding:6px 0;max-height:110px;overflow:auto}
.d-at-list li{padding:4px 12px 4px 14px;font-size:11px;color:var(--muted);border-left:2px solid transparent;cursor:pointer;transition:color 160ms var(--ease),border-color 160ms var(--ease)}
.d-at-list li.on{color:var(--ink);border-left-color:var(--ink-vermilion)}

init:
root => {
  var btn = root.querySelector('[data-play]');
  var list = root.querySelector('[data-list]');
  var time = root.querySelector('[data-time]');
  if (!btn || !list) return;
  var items = [].slice.call(list.children);
  var t = 0, on = false, timer = 0, dur = 12;
  var fmt = function (s) { return '00:' + (s < 10 ? '0' : '') + Math.floor(s); };
  var paint = function () {
    var active = null;
    items.forEach(function (li) { var start = Number(li.dataset.t) || 0; if (start <= t) active = li; li.classList.toggle('on', li === active); });
    if (active) { var top = active.offsetTop - list.clientHeight / 2 + 20; list.scrollTop = Math.max(0, top); }
    if (time) time.textContent = fmt(t) + ' / 00:12';
  };
  var tick = function () { t += .2; if (t >= dur) { t = 0; on = false; clearInterval(timer); btn.textContent = '▶ 播放录音'; } paint(); };
  btn.addEventListener('click', function () {
    on = !on;
    btn.textContent = on ? '❚❚ 暂停' : '▶ 播放录音';
    clearInterval(timer);
    if (on) timer = setInterval(tick, 200);
  });
  items.forEach(function (li) { li.addEventListener('click', function () { t = Number(li.dataset.t) || 0; paint(); }); });
  paint();
}
